// Aggregate all signals into one summary for analysis
const allSignals = $input.all();

// Create a summary of the week's signals
const summary = {
  total_signals: allSignals.length,
  date_range: {
    start: allSignals[0]?.json?.date || 'Unknown',
    end: allSignals[allSignals.length - 1]?.json?.date || 'Unknown'
  },
  signals_by_category: {},
  signals_by_sentiment: {},
  high_value_signals: [],
  all_signals: allSignals.map(item => item.json)
};

// Group by category and sentiment
allSignals.forEach(item => {
  const signal = item.json;

  // Count by category
  summary.signals_by_category[signal.category] = (summary.signals_by_category[signal.category] || 0) + 1;

  // Count by sentiment
  summary.signals_by_sentiment[signal.sentiment] = (summary.signals_by_sentiment[signal.sentiment] || 0) + 1;

  // Collect high-value signals
  if (signal.signal_strength === 'High') {
    summary.high_value_signals.push(signal);
  }
});

// Return single aggregated object for AI analysis
return summary;

// Simple, fast parsing to prevent timeouts - handles both Claude and DeepSeek formats
const data = $input.first();
const currentDate = new Date().toISOString().split('T')[0];

let analysisText = '';
let recommendations = [];
let debugInfo = [];

try {
  if (data.json && data.json.output) {
    analysisText = data.json.output;
  } else {
    analysisText = data.output || data.text || '';
  }

  const lines = analysisText.split('\n');
  let inBuySection = false;
  let inSellSection = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (line.includes('BUY:') || line.includes('**STRONG BUY') || line.includes('STRONG BUY') ||
        line.includes('**BUY Candidates') || line.includes('BUY Candidates')) {
      inBuySection = true; inSellSection = false; continue;
    }
    if (line.includes('SELL/AVOID:') || line.includes('**AVOID/SELL') || line.includes('AVOID/SELL') ||
        line.includes('**SELL Candidates') || line.includes('SELL Candidates')) {
      inBuySection = false; inSellSection = true; continue;
    }
    if (line.includes('## **MARKET SUMMARY') || line.includes('**MARKET SUMMARY**')) {
      inBuySection = false; inSellSection = false; break;
    }

    if (inBuySection || inSellSection) {
      const hasNumber = line.match(/^\d+\./);
      const hasBullet = line.includes('**') && line.includes('(') && line.includes(')');

      if (hasNumber || hasBullet) {
        if (line.includes('**High Conviction:**') || line.includes('**Medium Conviction:**') ||
            line.includes('**Avoid:**') || line.includes('%')) continue;

        const tickerMatch = line.match(/\*\*([A-Z]{2,5})\*\*/) || line.match(/\(([A-Z]{2,5})\)/) || line.match(/([A-Z]{2,5})/);
        if (tickerMatch) {
          const ticker = tickerMatch[1];
          let conviction = 'Medium Conviction';
          if (line.includes('High')) conviction = 'High Conviction';
          if (line.includes('Low')) conviction = 'Low Conviction';

          let reasoning = 'Market analysis';
          let reasoningParts = [];

          for (let j = i + 1; j < Math.min(i + 8, lines.length); j++) {
            const nextLine = lines[j].trim();
            if (nextLine.startsWith('- ') || nextLine.startsWith('* ') ||
                nextLine.startsWith('-') || nextLine.startsWith('*')) {
              const bulletText = nextLine.replace(/^[-*]\s*/, '').trim();
              if (bulletText && !bulletText.startsWith('**')) reasoningParts.push(bulletText);
            }
            if (nextLine.match(/^\d+\./) || nextLine.includes('###') ||
                (reasoningParts.length > 0 && nextLine === '')) break;
          }

          if (reasoningParts.length > 0) {
            reasoning = reasoningParts.join('; ').substring(0, 200);
          } else {
            const reasoningMatch = line.match(/[-–]\s*(.+)$/) || line.match(/:\s*(.+)$/);
            if (reasoningMatch) reasoning = reasoningMatch[1].trim();
          }

          recommendations.push({
            date: currentDate,
            action: inBuySection ? 'BUY' : 'SELL',
            ticker: ticker,
            conviction: conviction,
            reasoning: reasoning,
            signal_quality: 8,
            overall_sentiment: 'Mixed to Positive'
          });
        }
      }
    }
  }
} catch (error) {
  recommendations = [{ date: currentDate, action: 'ERROR', ticker: 'PARSE_ERROR', conviction: 'N/A', reasoning: error.message, signal_quality: 8, overall_sentiment: 'Unknown' }];
}

if (recommendations.length === 0) {
  recommendations = [{ date: currentDate, action: 'NO_RECS', ticker: 'NONE', conviction: 'N/A', reasoning: 'No recommendations found', signal_quality: 8, overall_sentiment: 'Unknown' }];
}

return recommendations;

const inputData = $input.first();
let markdownText = '';

if (typeof inputData === 'string') {
  try {
    const parsed = JSON.parse(inputData);
    if (parsed.json && parsed.json.output) markdownText = parsed.json.output;
  } catch (error) {
    markdownText = inputData;
  }
} else if (inputData && typeof inputData === 'object') {
  if (inputData.json && inputData.json.output) markdownText = inputData.json.output;
  else if (inputData.output) markdownText = inputData.output;
  else markdownText = JSON.stringify(inputData);
}

if (!markdownText || markdownText.length === 0) {
  return { error: 'Could not extract text from input' };
}

let htmlContent = markdownText
  .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  .replace(/###?\s*\*\*([^*]+)\*\*/g, '<h3>$1</h3>')
  .replace(/##\s*\*\*([^*]+)\*\*/g, '<h2>$1</h2>')
  .replace(/\n\n/g, '|||PARAGRAPH|||')
  .replace(/^[-*]\s+(.+)$/gm, '<li>$1</li>')
  .replace(/^(\d+)\.\s+(.+)$/gm, '<li>$2</li>')
  .replace(/(<li>.*?<\/li>\n?)+/gs, '<ul>$&</ul>')
  .replace(/\n/g, '<br>')
  .replace(/\|\|\|PARAGRAPH\|\|\|/g, '</p><p>');

htmlContent = htmlContent
  .replace(/<ul>(<li>.*?<\/li>)<br>/gs, '<ul>$1')
  .replace(/<\/li><br><li>/gs, '</li><li>')
  .replace(/<\/ul><br><ul>/gs, '</ul><ul>');

if (!htmlContent.startsWith('<p>') && !htmlContent.startsWith('<h')) {
  htmlContent = '<p>' + htmlContent + '</p>';
}

return { html_content: htmlContent, success: true };
